import hashlib
import json

def operation_key(
    tenant_id,
    operation_id,
    operation,
    parameters
):

    payload = json.dumps(
        {
            "tenant": tenant_id,
            "operation_id": operation_id,
            "operation": operation,
            "parameters": parameters
        },
        sort_keys=True,
        separators=(",", ":")
    )

    return hashlib.sha256(
        payload.encode()
    ).hexdigest()

